  transition: all 2s ease-in-out;
}

/* naga kiri */
.naga-kiri {
  left: -50%;
  background-image: url("https://imgsaya3.io/images/2025/10/31/RJBGIFNAGA.gif");
  background-position: left center;
  transform: translateY(-50%) scaleX(1);
}

/* naga kanan */
.naga-kanan {
  right: -50%;
